class Solution:
    def oddEvenJumps(self, arr: list[int]) -> int:
        from sortedcontainers import SortedDict
        n = len(arr)
        odd = [False] * n
        even = [False] * n
        odd[-1] = even[-1] = True
        sd = SortedDict()
        sd[arr[-1]] = n - 1
        for i in range(n - 2, -1, -1):
            val = arr[i]
            idx = sd.bisect_left(val)
            if idx < len(sd):
                odd[i] = even[sd.values()[idx]]
            idx2 = sd.bisect_right(val) - 1
            if idx2 >= 0:
                even[i] = odd[sd.values()[idx2]]
            sd[val] = i
        return sum(odd)

